[Workspace Update - Frontend Developer]

Thanks for the clarifications and confirming backend support details. This helps finalize the UI design and data flow.

Based on your input, here’s my plan for the Profile Management UI:

- **Fields**: Editable Display Name (text input), Bio (textarea), Avatar URL (text input).
- **Validation**: Client-side checks for required fields and URL format for Avatar URL before PATCH.
- **State management**: Maintain form state with initial profile data, track dirty state for enabling/disabling Save and Cancel.
- **Optimistic concurrency**: Include `updated_at` timestamp in PATCH payload if available.
- **Error handling**: Display inline validation errors returned from backend near relevant inputs.
- **Extensibility**: Use a form config or schema so new fields can be added easily later.
- **Buttons**: “Save” to submit changes, “Cancel” to revert unsaved changes to last saved state.
- **UX**: Disable Save if no changes, indicate save in-progress, show success/error messages.

---

To move forward quickly, here is a React prototype snippet illustrating the core form and state flow:

```jsx
import React, { useState, useEffect } from 'react';

function ProfileForm({ initialProfile, onSave }) {
  const [formData, setFormData] = useState({
    displayName: '',
    bio: '',
    avatarUrl: '',
  });
  const [updatedAt, setUpdatedAt] = useState(null);
  const [errors, setErrors] = useState({});
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (initialProfile) {
      setFormData({
        displayName: initialProfile.displayName || '',
        bio: initialProfile.bio || '',
        avatarUrl: initialProfile.avatarUrl || '',
      });
      setUpdatedAt(initialProfile.updated_at || null);
      setDirty(false);
      setErrors({});
    }
  }, [initialProfile]);

  const validate = () => {
    const newErrors = {};
    if (!formData.displayName.trim()) {
      newErrors.displayName = 'Display Name is required.';
    }
    if (formData.avatarUrl && !/^https?:\/\/.+\..+/.test(formData.avatarUrl)) {
      newErrors.avatarUrl = 'Avatar URL must be a valid URL.';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (field) => (e) => {
    setFormData({...formData, [field]: e.target.value});
    setDirty(true);
  };

  const handleCancel = () => {
    if (initialProfile) {
      setFormData({
        displayName: initialProfile.displayName || '',
        bio: initialProfile.bio || '',
        avatarUrl: initialProfile.avatarUrl || '',
      });
      setErrors({});
      setDirty(false);
    }
  };

  const handleSave = async () => {
    if (!validate()) return;
    setSaving(true);
    setErrors({});
    try {
      // Prepare partial update payload with changed fields only
      const patchPayload = {};
      if (formData.displayName !== initialProfile.displayName) patchPayload.displayName = formData.displayName;
      if (formData.bio !== initialProfile.bio) patchPayload.bio = formData.bio;
      if (formData.avatarUrl !== initialProfile.avatarUrl) patchPayload.avatarUrl = formData.avatarUrl;
      if (updatedAt) patchPayload.updated_at = updatedAt;

      const updatedProfile = await onSave(patchPayload);
      // Update form with latest saved profile
      setFormData({
        displayName: updatedProfile.displayName || '',
        bio: updatedProfile.bio || '',
        avatarUrl: updatedProfile.avatarUrl || '',
      });
      setUpdatedAt(updatedProfile.updated_at || null);
      setDirty(false);
    } catch (err) {
      if (err.validationErrors) {
        setErrors(err.validationErrors);
      } else {
        // handle other error types (e.g. network)
        alert('Save failed: ' + err.message);
      }
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={e => { e.preventDefault(); handleSave(); }}>
      <div>
        <label>
          Display Name
          <input
            type="text"
            value={formData.displayName}
            onChange={handleChange('displayName')}
            disabled={saving}
          />
        </label>
        {errors.displayName && <div className="error">{errors.displayName}</div>}
      </div>
      <div>
        <label>
          Bio
          <textarea
            value={formData.bio}
            onChange={handleChange('bio')}
            disabled={saving}
          />
        </label>
        {errors.bio && <div className="error">{errors.bio}</div>}
      </div>
      <div>
        <label>
          Avatar URL
          <input
            type="text"
            value={formData.avatarUrl}
            onChange={handleChange('avatarUrl')}
            disabled={saving}
          />
        </label>
        {errors.avatarUrl && <div className="error">{errors.avatarUrl}</div>}
      </div>
      <button type="submit" disabled={!dirty || saving}>Save</button>
      <button type="button" onClick={handleCancel} disabled={!dirty || saving}>Cancel</button>
      {saving && <span>Saving...</span>}
    </form>
  );
}

export default ProfileForm;
```

